const e=[{id:"daniel-costa",name:"Daniel Costa",initials:"DC",avatarTone:"ink",archetypeId:"adult-adv",archetype:"Adult · Advanced",phone:"+359 88 421 0918",age:31,ntrp:5,style:"All-courter",grip:"Eastern · Two-handed BH",handed:"Right-handed",hasRacket:!0,ballType:"yellow",preferences:"Wants serious technical feedback. Prefers 90-min sessions. Will play in rain.",cadence:"Twice weekly",createdAt:"2026-01-15T09:00:00.000Z",updatedAt:"2026-05-21T17:00:00.000Z"},{id:"charlotte-whitfield-hayes",name:"Charlotte Whitfield-Hayes",initials:"CW",avatarTone:"default",archetypeId:"adult-int",archetype:"Adult · Intermediate",phone:"+44 7700 900 184",age:38,ntrp:3.5,style:"Social · Volleyer",grip:"Continental serve · Eastern FH",handed:"Right-handed",hasRacket:!0,ballType:"yellow",preferences:"Here for the people, not the trophy. Loves doubles drills. Will bring a friend. Keep it light, keep it fun.",cadence:"Weekly · Mondays",createdAt:"2026-02-01T09:00:00.000Z",updatedAt:"2026-05-20T12:00:00.000Z"},{id:"eleni-vasilakos",name:"Eleni Vasilakos",initials:"EV",avatarTone:"default",archetypeId:"adult-beg",archetype:"Adult · Beginner",phone:"+30 694 558 2210",age:42,ntrp:2,style:"Recreational",grip:"Eastern FH (learning)",handed:"Right-handed",hasRacket:!1,ballType:"yellow",preferences:"Wants to get outside, build a habit. No tournaments, no pressure. Encouragement matters more than correction.",cadence:"Weekly · Fridays",createdAt:"2026-03-10T09:00:00.000Z",updatedAt:"2026-05-16T19:00:00.000Z"},{id:"theo-marchetti",name:"Theo Marchetti",initials:"TM",avatarTone:"clay",archetypeId:"junior",archetype:"Junior · Red ball",phone:"+39 333 412 9087 · (Sofia, mum)",age:5,ntrp:null,style:"First sessions",grip:"N/A — foam ball, hand-feed",handed:"Right-handed (probably)",hasRacket:!0,ballType:"red",preferences:'Max 30 min. Loves the "rabbit run" warm-up. Bring stickers. Treat-based reward kept session two together.',cadence:"Weekly · Sat mornings",createdAt:"2026-04-01T09:00:00.000Z",updatedAt:"2026-05-18T10:30:00.000Z"},{id:"henley-juniors",name:"Henley Juniors",initials:"HJ",avatarTone:"clay",archetypeId:"group",archetype:"Group · 4 kids",phone:"+44 7700 902 441 · (Mark Henley, parent coord)",age:null,ntrp:null,style:"Ages 7, 7, 9, 10",grip:"Mixed",handed:"Mixed",hasRacket:!1,ballType:"orange",preferences:"Parents organised this together. Wednesday afternoons. Keep it active — boredom is the enemy. Game-based.",cadence:"Weekly · Wednesdays",members:["Olive (10)","Sam (9)","Theo H. (7)","Iris (7)"],createdAt:"2026-02-15T09:00:00.000Z",updatedAt:"2026-05-14T17:00:00.000Z"},{id:"margot-beaumont",name:"Margot Beaumont",initials:"MB",avatarTone:"default",archetypeId:"adult-adv",archetype:"Adult · Advanced",phone:"+33 6 18 22 47 03",age:29,ntrp:4.5,style:"Baseliner · Heavy topspin",grip:"Semi-Western FH · Two-handed BH",handed:"Right-handed",hasRacket:!0,ballType:"yellow",preferences:"Match prep oriented. Wants live-ball drills and pattern repetition. Hates fitness theatre — wants tennis fitness.",cadence:"Twice weekly",createdAt:"2026-01-20T09:00:00.000Z",updatedAt:"2026-05-21T09:18:00.000Z"},{id:"ravi-patel",name:"Ravi Patel",initials:"RP",avatarTone:"default",archetypeId:"adult-int",archetype:"Adult · Intermediate",phone:"+44 7911 482 003",age:34,ntrp:3,style:"Counterpuncher",grip:"Eastern FH · One-handed BH (learning slice)",handed:"Right-handed",hasRacket:!0,ballType:"yellow",preferences:'Engineer brain — likes the "why". Send drill PDFs. He will study them.',cadence:"Weekly · Saturdays",createdAt:"2026-02-20T09:00:00.000Z",updatedAt:"2026-05-17T15:10:00.000Z"},{id:"alex-kim",name:"Alex Kim",initials:"AK",avatarTone:"default",archetypeId:"junior",archetype:"Junior · Competitive",phone:"+1 408 555 0193 · (Min, dad)",age:14,ntrp:4,style:"Aggressive baseliner",grip:"Semi-Western · Two-handed BH",handed:"Left-handed",hasRacket:!0,ballType:"yellow",preferences:"Tournament track. Dad sits courtside. Parent dynamic real — communicate plan in writing after each session.",cadence:"Weekly · Saturdays",createdAt:"2026-03-01T09:00:00.000Z",updatedAt:"2026-05-18T16:40:00.000Z"}],t=[{id:"n-dc-1",clientId:"daniel-costa",body:"Backhand return on deuce side dipping into net — opens shoulder too early. Cued split-step on toss recognition. Better by end.",tags:["Backhand"],createdAt:"2026-05-19T18:48:00.000Z"},{id:"n-dc-2",clientId:"daniel-costa",body:"Serve speed up ~8mph after platform-stance tweak. Slice serve out-wide is now a real weapon. Don't lose it.",tags:["Serve"],createdAt:"2026-05-16T09:12:00.000Z"},{id:"n-dc-3",clientId:"daniel-costa",body:"Wants to drill kick serve for the Plovdiv tournament. Three weeks out.",tags:["Serve"],createdAt:"2026-05-14T17:35:00.000Z"},{id:"n-dc-4",clientId:"daniel-costa",body:"Fitness fine. Footwork on the run-around forehand still adjusts late. Run shadow patterns next session.",tags:["Footwork","Forehand"],createdAt:"2026-05-12T17:55:00.000Z"},{id:"n-cw-1",clientId:"charlotte-whitfield-hayes",body:"Brought Pippa again — net play drills both. Charlotte's touch volleys actually pretty good when she stops thinking.",tags:["Tactics"],createdAt:"2026-05-20T12:08:00.000Z"},{id:"n-cw-2",clientId:"charlotte-whitfield-hayes",body:"Asked about the club mixer next month — confirmed both for Saturday slot.",tags:[],createdAt:"2026-05-13T12:02:00.000Z"},{id:"n-cw-3",clientId:"charlotte-whitfield-hayes",body:"Hated the baseline conditioning, loved the king-of-the-court doubles. Note for future planning.",tags:["Tactics"],createdAt:"2026-05-06T12:00:00.000Z"},{id:"n-ev-1",clientId:"eleni-vasilakos",body:"First rally past 6 balls today — was visibly thrilled. Build on that. Keep targets achievable.",tags:["Forehand"],createdAt:"2026-05-16T18:55:00.000Z"},{id:"n-ev-2",clientId:"eleni-vasilakos",body:"Grip slipping back to frying-pan under pressure. Tape the racquet for visual reference.",tags:["Forehand"],createdAt:"2026-05-09T18:50:00.000Z"},{id:"n-tm-1",clientId:"theo-marchetti",body:"Tracked the ball with his eyes for a full minute today. That is huge. Sofia happy.",tags:["Footwork"],createdAt:"2026-05-18T10:33:00.000Z"},{id:"n-tm-2",clientId:"theo-marchetti",body:"Lost interest at ~22 min. Lesson 2 ended early — fine. Don't push it.",tags:["Mental"],createdAt:"2026-05-11T10:30:00.000Z"},{id:"n-tm-3",clientId:"theo-marchetti",body:'First session. Mostly tag and "find the cone". Goal was: come back next week. Did.',tags:[],createdAt:"2026-05-04T10:30:00.000Z"},{id:"n-hj-1",clientId:"henley-juniors",body:"Iris is finally swinging across the body, not pushing. Sam is bored — needs harder targets. Split next week.",tags:["Forehand","Tactics"],createdAt:"2026-05-14T17:08:00.000Z"},{id:"n-hj-2",clientId:"henley-juniors",body:'"World cup" round-robin worked. Do again. Olive won, very proud.',tags:["Tactics"],createdAt:"2026-05-07T17:05:00.000Z"},{id:"n-mb-1",clientId:"margot-beaumont",body:"Crosscourt-deep / inside-out forehand pattern — clean 7/10 reps once she committed. Stop hedging the second ball.",tags:["Forehand","Tactics"],createdAt:"2026-05-21T09:18:00.000Z"},{id:"n-mb-2",clientId:"margot-beaumont",body:"Serve toss drifting back-and-left on second serve. Toss-from-a-shelf drill helped briefly.",tags:["Serve"],createdAt:"2026-05-17T09:15:00.000Z"},{id:"n-rp-1",clientId:"ravi-patel",body:"Slice backhand finally has carry — keep it low. Footwork still wide on approach.",tags:["Backhand","Footwork"],createdAt:"2026-05-17T15:10:00.000Z"},{id:"n-ak-1",clientId:"alex-kim",body:"Lefty serve out-wide on ad side — when he commits, untouchable. He doesn't commit enough.",tags:["Serve","Mental"],createdAt:"2026-05-18T16:40:00.000Z"}];export{e as SEED_CLIENTS,t as SEED_NOTES};
